class Solution { public: int waysToMakeFair(vector<int>& nums){int totalEven=0,totalOdd=0;for(int i=0;i<(int)nums.size();++i)(i%2?totalOdd:totalEven)+=nums[i];int leftEven=0,leftOdd=0,answer=0;for(int i=0;i<(int)nums.size();++i){int rightEven=totalEven-leftEven-(i%2?0:nums[i]);int rightOdd=totalOdd-leftOdd-(i%2?nums[i]:0);answer+=leftEven+rightOdd==leftOdd+rightEven;(i%2?leftOdd:leftEven)+=nums[i];}return answer;} };
